    /** Database decimal representation; never turn monetary totals into floats. */
    private static function decimal($value):string {$value=trim((string)$value);if(!preg_match('/^\d+(?:\.\d{1,2})?$/',$value))return '0.00';[$whole,$fraction]=array_pad(explode('.',$value,2),2,'');return (ltrim($whole,'0')?:'0').'.'.str_pad($fraction,2,'0');}
